--Which city has the highest return rate, 
--and what are the common products returned from that city?
select cs.customer_city as city, count(r.is_returned) as total_returns from 
vw_returns r join vw_customer_segmentation cs on 
r.customer_id = cs.customer_id
where r.is_returned = 1
group by cs.customer_city
order by total_returns desc;


